// Generated by scripts/build.js. Edit scripts/sw.template.js instead.
// Online: always fetch the newest files (network first). Offline: use the saved copy.
// Install only waits for the small app shell; lessons and art are cached in the background.
const V='polis-__VERSION__',FILES=__FILES__;
const SHELL=FILES.filter(f=>!/lessons\/\d|^subjects\/[^/]+\/lessons\/\d|^art\//.test(f));
self.addEventListener('install',e=>{e.waitUntil(caches.open(V).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',e=>{e.waitUntil((async()=>{
  for(const k of await caches.keys())if(k!==V&&k!==V+'-fonts')await caches.delete(k);
  await self.clients.claim();
  const c=await caches.open(V);
  for(const f of FILES.filter(f=>!SHELL.includes(f))){try{if(!(await c.match(f)))await c.add(f)}catch(err){}}
})())});
self.addEventListener('fetch',e=>{
  const u=new URL(e.request.url);if(e.request.method!=='GET')return;
  if(u.host.endsWith('googleapis.com')||u.host.endsWith('gstatic.com')){
    e.respondWith(caches.open(V+'-fonts').then(c=>c.match(e.request).then(r=>r||fetch(e.request).then(n=>{c.put(e.request,n.clone());return n}))));return}
  if(u.origin!==location.origin||u.pathname.startsWith('/api/'))return;
  e.respondWith(fetch(e.request).then(n=>{if(n.ok){const cp=n.clone();caches.open(V).then(c=>c.put(e.request,cp))}return n})
    .catch(()=>caches.match(e.request,{ignoreSearch:true})));
});
self.addEventListener('push',e=>{let d={};try{d=e.data.json()}catch(x){d={title:'Light Bulb',body:e.data&&e.data.text()}}
  e.waitUntil(self.registration.showNotification(d.title||'Light Bulb',{body:d.body||'',icon:'icons/icon-192.png',badge:'icons/icon-192.png',tag:'daily',renotify:true,data:{url:d.url||'./'}}))});
self.addEventListener('notificationclick',e=>{e.notification.close();const url=new URL(e.notification.data.url,self.location.origin).href;
  e.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(cs=>{for(const c of cs){if('focus' in c){c.navigate(url);return c.focus()}}return clients.openWindow(url)}))});
